def run(product_page):
    page = product_page if isinstance(product_page, dict) else {}
    text = page.get('text') or ''
    if not isinstance(text, str):
        text = ''
    text = ' '.join(text.split())
    if len(text) > 6000:
        text = text[:6000]
    return {'text': text}

def run(independent_reviews, alternatives):
    def pick(results):
        out = []
        if isinstance(results, dict):
            items = results.get('results')
            if isinstance(items, list):
                for r in items[:5]:
                    if isinstance(r, dict):
                        out.append({'title': (r.get('title') or '')[:160], 'url': r.get('url') or '', 'snippet': (r.get('content') or '')[:260]})
        return out
    return {'independent_reviews': pick(independent_reviews), 'alternatives': pick(alternatives)}

def run(price, currency, rates_json, budget_usd):
    def safe_num(x):
        try:
            return float(x)
        except Exception:
            return None
    p = safe_num(price)
    cur = (currency or '').strip().upper() if isinstance(currency, str) else ''
    usd = None
    rate = None
    if p is not None and cur == 'USD':
        usd = p
        rate = 1.0
    elif p is not None and isinstance(rates_json, dict):
        rates = rates_json.get('rates') if isinstance(rates_json.get('rates'), dict) else {}
        r = rates.get('USD')
        try:
            rate = float(r)
        except Exception:
            rate = None
        if rate is not None:
            usd = p * rate
    return {'price': p, 'currency': cur or None, 'usd_price': usd, 'rate_to_usd': rate, 'budget_usd': budget_usd}

def run(product_page, llm_extract, converted):
    page = product_page if isinstance(product_page, dict) else {}
    llm_extract = llm_extract if isinstance(llm_extract, dict) else {}
    converted = converted if isinstance(converted, dict) else {}
    problems = []
    if page.get('status') != 200:
        problems.append('Amazon page did not return HTTP 200.')
    text = page.get('text') or ''
    if not isinstance(text, str) or not text.strip():
        problems.append('Amazon page text was empty.')
    if not llm_extract.get('title'):
        problems.append('Title could not be extracted.')
    if llm_extract.get('price') is None:
        problems.append('Price could not be extracted.')
    if not llm_extract.get('currency'):
        problems.append('Currency could not be extracted.')
    if converted.get('price') is None:
        problems.append('Converted price data is missing.')
    ok = page.get('status') == 200 and bool(text.strip()) and bool(llm_extract.get('title')) and llm_extract.get('price') is not None and bool(llm_extract.get('currency')) and converted.get('price') is not None
    return {'ok': ok, 'problems': problems}

def run(llm_extract, converted, verify, search_facts, budget_usd):
    llm_extract = llm_extract if isinstance(llm_extract, dict) else {}
    converted = converted if isinstance(converted, dict) else {}
    verify = verify if isinstance(verify, dict) else {}
    search_facts = search_facts if isinstance(search_facts, dict) else {}
    reasons = []
    score = 0
    escalate = False
    escalate_reddit = False
    verdict = 'wait'
    if not verify.get('ok'):
        reasons.append('Product page data was not verified.')
        escalate = True
        return {'score': 0, 'verdict': 'wait', 'reasons': reasons, 'escalate': True, 'escalate_reddit': False}
    price_usd = converted.get('usd_price')
    try:
        budget = float(budget_usd) if budget_usd is not None else 100.0
    except Exception:
        budget = 100.0
    if isinstance(price_usd, (int, float)):
        score += 1
        if price_usd <= budget:
            score += 1
            reasons.append('Price is within budget.')
        else:
            reasons.append('Price is above budget.')
        if price_usd > 100:
            escalate = True
            reasons.append('Price is above about 100 USD.')
    else:
        reasons.append('USD price could not be computed.')
        escalate = True
    reviews = search_facts.get('independent_reviews') if isinstance(search_facts.get('independent_reviews'), list) else []
    alts = search_facts.get('alternatives') if isinstance(search_facts.get('alternatives'), list) else []
    if reviews:
        score += 1
        reasons.append('Independent review hits were found.')
    if alts:
        score += 1
        reasons.append('Cheaper alternatives were found.')
    cheap_disagree = bool(reviews) and bool(alts)
    if cheap_disagree:
        escalate = True
        reasons.append('Cheap signals disagree.')
        if isinstance(price_usd, (int, float)) and price_usd > 100:
            escalate_reddit = True
    if isinstance(price_usd, (int, float)) and price_usd > budget and alts and not cheap_disagree:
        verdict = 'pick-an-alternative'
    elif isinstance(price_usd, (int, float)) and price_usd <= budget and not cheap_disagree and not verify.get('problems'):
        verdict = 'buy'
    elif alts and (cheap_disagree or (isinstance(price_usd, (int, float)) and price_usd > budget)):
        verdict = 'pick-an-alternative'
    else:
        verdict = 'wait'
    return {'score': score, 'verdict': verdict, 'reasons': reasons, 'escalate': escalate, 'escalate_reddit': escalate_reddit}

def run(amazon_url, budget_usd, llm_extract, converted, verify, judge, product_reality_check, reddit_research, search_facts):
    def clean(x):
        return ' '.join(str(x).split()) if x is not None else ''
    llm_extract = llm_extract if isinstance(llm_extract, dict) else {}
    converted = converted if isinstance(converted, dict) else {}
    verify = verify if isinstance(verify, dict) else {}
    judge = judge if isinstance(judge, dict) else {}
    title = clean(llm_extract.get('title')) or 'the product'
    price = converted.get('usd_price')
    verdict = judge.get('verdict', 'wait')
    reasons = judge.get('reasons') or []
    pr = clean(product_reality_check.get('result')) if isinstance(product_reality_check, dict) else ''
    rr = clean(reddit_research.get('result')) if isinstance(reddit_research, dict) else ''
    if not verify.get('ok'):
        speech = f'Wait on {title}. I could not verify the page cleanly, so I would not trust a purchase decision yet.'
    else:
        if verdict == 'buy':
            speech = f'Buy {title}. The price looks reasonable and the signals are steady.'
        elif verdict == 'pick-an-alternative':
            speech = f'Pick an alternative to {title}. The signals point to a better-value option nearby.'
        else:
            speech = f'Wait on {title}. The deal does not look clean enough for a confident buy.'
    lines = ['# Amazon Buy Check', '', '## Verdict']
    lines.append(f'- **Decision:** {verdict}')
    lines.append(f'- **Product:** {title}')
    lines.append(f'- **URL:** {clean(llm_extract.get("url")) or amazon_url}')
    lines.append(f'- **Price (USD):** ${price:.2f}' if isinstance(price, (int, float)) else '- **Price (USD):** unknown')
    lines.append(f'- **Budget:** ${float(budget_usd):.2f}' if budget_usd is not None else '- **Budget:** not set')
    lines.append('')
    lines.append('## Reasons')
    for r in reasons[:8]:
        lines.append(f'- {clean(r)}')
    if verify.get('problems'):
        lines.append('')
        lines.append('## Verification problems')
        for p in verify.get('problems', [])[:8]:
            lines.append(f'- {clean(p)}')
    if pr:
        lines.append('')
        lines.append('## Product Reality Check')
        lines.append(pr)
    if rr:
        lines.append('')
        lines.append('## Reddit Research')
        lines.append(rr)
    if search_facts.get('independent_reviews'):
        lines.append('')
        lines.append('## Independent review hits')
        for hit in search_facts.get('independent_reviews', [])[:5]:
            if isinstance(hit, dict):
                lines.append(f'- {clean(hit.get("title"))}: {clean(hit.get("snippet"))} {clean(hit.get("url"))}')
    if search_facts.get('alternatives'):
        lines.append('')
        lines.append('## Cheaper alternatives')
        for hit in search_facts.get('alternatives', [])[:5]:
            if isinstance(hit, dict):
                lines.append(f'- {clean(hit.get("title"))}: {clean(hit.get("snippet"))} {clean(hit.get("url"))}')
    report = '\n'.join(lines)
    return {'speech': speech[:900], 'report': report}
